	static string LINES_AFTER_BLOCKS_OPTION =
		GROUP_TITLE + Options.DELIMITER + "Lines After Basic Blocks";

	static string DEFAULT_FLAG_COMMENT;

	static string FUN_EXIT_FLAG_LEADER = "********** ";
	static string FUN_EXIT_FLAG_TAIL = " Exit ********** ";

